patch.before:
/* Loaded only by the isolated laptop-test subtree. */
.fmz-owner-test-active{padding-top:74px!important}
.fmz-test-banner,.fmz-test-guide,.fmz-test-dialog,.fmz-test-mini{font-family:inherit;color:#f5f3eb;box-sizing:border-box;overflow-wrap:anywhere}
.fmz-test-banner{position:fixed;inset:0 0 auto;z-index:9999;min-height:66px;display:flex;align-items:center;gap:12px;padding:10px 18px;background:#17140b;border-bottom:2px solid #d8bb69;box-shadow:0 4px 18px #0008}
.fmz-test-banner strong{color:#f8d97d;letter-spacing:.08em;white-space:nowrap}.fmz-test-banner>span{flex:1;font-size:.9rem}
.fmz-test-banner button,.fmz-test-guide button,.fmz-test-dialog button,.fmz-test-mini button{min-height:44px;border:1px solid #b99a4f;border-radius:10px;padding:9px 13px;background:#211e14;color:#fff1c6;font:inherit;line-height:1.35;cursor:pointer;max-width:100%;white-space:normal}
.fmz-test-banner button:focus-visible,.fmz-test-guide :focus-visible,.fmz-test-dialog :focus-visible,.fmz-test-mini :focus-visible{outline:3px solid #ffe298;outline-offset:3px}
.fmz-test-guide button:disabled,.fmz-test-dialog button:disabled,.fmz-test-mini button:disabled{opacity:.5;cursor:default}
.fmz-test-guide{position:fixed;top:86px;right:16px;z-index:9998;width:min(390px,calc(100vw - 32px));max-height:calc(100dvh - 104px);overflow:auto;padding:18px;background:#0c1118;border:1px solid #d8bb69;border-radius:16px;box-shadow:0 16px 60px #000b;scrollbar-gutter:stable}
.fmz-test-guide[hidden]{display:none}.fmz-test-guide header,.fmz-test-dialog>header{display:flex;justify-content:space-between;align-items:start;gap:12px}.fmz-test-guide h2{font-size:1.2rem;margin:.5rem 0}.fmz-test-guide p,.fmz-test-dialog p,.fmz-test-mini p{line-height:1.55}.fmz-test-step{color:#e5c978;font-weight:700}.fmz-test-small{font-size:.85rem;color:#c0c4ca}
.fmz-test-actions{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.fmz-test-actions button{flex:1 1 130px}.fmz-test-guide ol{padding-left:22px}.fmz-test-guide li{margin:8px 0}.fmz-test-guide li button{width:100%;text-align:left}.fmz-test-guide li button[aria-current]{border-width:3px}.fmz-test-guide li span{color:#edda95}.fmz-test-guide summary,.fmz-test-dialog summary,.fmz-test-mini summary{cursor:pointer;min-height:44px;padding:10px 0;font-weight:700}
.fmz-test-dialog{width:min(850px,calc(100vw - 24px));max-height:calc(100dvh - 24px);margin:auto;padding:22px;border:1px solid #d8bb69;border-radius:16px;background:#0c1118;overflow:auto}.fmz-test-dialog::backdrop{background:#000b}.fmz-test-dialog h2{margin:0;font-size:1.35rem}.fmz-test-dialog label{display:grid;gap:8px;margin:15px 0}.fmz-test-dialog select,.fmz-test-dialog input:not([type=checkbox]){width:100%;min-height:44px;padding:10px;color:#f5f3eb;background:#171e27;border:1px solid #777;border-radius:8px;font:inherit}.fmz-test-dialog .fmz-test-check{display:flex;align-items:start;gap:12px}.fmz-test-check input{min-width:22px;width:22px;height:22px;margin-top:3px}.fmz-test-dialog pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font:inherit;line-height:1.5;padding:12px;background:#171e27;border-radius:10px}.fmz-test-history{border-top:1px solid #5e5538;padding:14px 0}.fmz-test-history p{margin:5px 0}.fmz-test-warning{padding:10px;border-left:3px solid #d8bb69;background:#201d14;color:#ffe6a4}
.fmz-test-mini{padding:10px 14px;margin:8px;border:1px solid #d8bb69;border-radius:10px;background:#17140b;font-size:.92rem}.fmz-test-mini h3{font-size:1rem}.fmz-test-mini>summary{color:#f8d97d}.fmz-test-mini .fmz-test-actions{margin-bottom:4px}
@media(max-width:650px){.fmz-test-banner{gap:6px;padding:6px 10px;flex-wrap:wrap}.fmz-test-banner>span{flex-basis:calc(100% - 125px);font-size:.75rem}.fmz-test-banner button{font-size:.8rem;min-height:36px}.fmz-owner-test-active{padding-top:112px!important}.fmz-test-guide{top:120px;right:8px;width:calc(100vw - 16px);max-height:calc(100dvh - 132px)}.fmz-test-dialog{padding:14px}.fmz-test-dialog h2{font-size:1.1rem}}
@media(prefers-reduced-motion:reduce){.fmz-test-guide,.fmz-test-dialog{scroll-behavior:auto}}
/* The guide is an overlay and never takes width from the member profile. */
/* Local reminders are reused in Dashboard and the existing Agenda view. */
.fmz-test-reminder-surface{margin:18px 0;padding:18px;border:1px solid #8b793f;border-radius:14px;background:#12161c;overflow-wrap:anywhere}
.fmz-test-reminder-surface h2{font-size:1.1rem}.fmz-test-reminder-surface button{min-height:44px;padding:10px 14px;border:1px solid #b99a4f;border-radius:10px;background:#211e14;color:#fff1c6;font:inherit;cursor:pointer}
.fmz-test-reminder-surface button:focus-visible{outline:3px solid #ffe298;outline-offset:3px}

.fmz-test-guide header{align-items:center}.fmz-test-guide header>button{flex:0 0 auto;white-space:nowrap}.fmz-test-guide{max-width:calc(100vw - 24px)}.fmz-test-guide button,.fmz-test-banner button{word-break:normal;overflow-wrap:normal}.fmz-test-reminder-members{padding-left:22px}.fmz-test-reminder-members li{margin:8px 0}

/* Only the isolated owner test loads this layout. */
