body.ot-navigation .ot-builder-assignment button{white-space:normal}
body.ot-navigation.ot-builder-active #trainingCopyPanel,body.ot-navigation.ot-builder-active [data-publish-training],body.ot-navigation.ot-builder-active #trainingGoalStrip,body.ot-navigation.ot-builder-active [data-training-log],body.ot-navigation.ot-builder-active #training .exercise-log,body.ot-navigation.ot-builder-active [data-training-attendance],body.ot-navigation.ot-builder-active [data-save-training-day],body.ot-navigation.ot-builder-active [data-complete-training],body.ot-navigation .members-profile-page #trainingCopyPanel{display:none!important}
