@media(max-width:800px){.ot-calendar-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ot-calendar-cell{min-height:70px}}@media(max-width:420px){.ot-calendar-grid{grid-template-columns:1fr}}

/* Only loaded in the synthetic owner-test. No production API or database migration. */
(function(root){
 'use strict';
 const copy=value=>structuredClone(value),text=value=>typeof value==='string'||typeof value==='number'?String(value):'';
 const fields=['day','exercise','sets','reps','rest','tempo','group','equipment','image','targetRir','targetRpe','targetRIR','targetRPE','rirTarget','rpeTarget','schemaInstructions','generalInstructions'];
 const sha=async value=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(value)))),x=>x.toString(16).padStart(2,'0')).join('');
 function structure(entries){return (Array.isArray(entries)?entries:[]).map(entry=>Object.fromEntries(fields.filter(key=>Object.hasOwn(entry,key)).map(key=>[key,text(entry[key])])));}
 function valid(entries){if(!entries.length)throw Error('Dit schema bevat geen oefeningen.');for(const e of entries)if(!e.exercise?.trim()||!['Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag','Zondag'].includes(e.day)||!/^\d+$/.test(e.sets)||Number(e.sets)<1||Number(e.sets)>100||!e.reps?.trim())throw Error('Controleer trainingsdag, oefening, sets en herhalingen.');}
 function createService(adapter,hooks){
  let queue=Promise.resolve();const serial=fn=>{const job=queue.catch(()=>{}).then(fn);queue=job;return job;};
  function authorize(){const s=adapter.getState();if(s.synthetic!==true||s.closed||s.fakeActor!=='trainer')throw Error('Alleen de aangemelde synthetische trainer kan schema’s kopiëren.');return s;}
  function data(){authorize();return copy(adapter.getState().guide.schemaCopies||{version:1,versions:[],operations:[]});}
  async function write(value,patch={}){authorize();if(adapter.patchGuide)await adapter.patchGuide({...patch,schemaCopies:value});else await adapter.setGuide({...adapter.getState().guide,...patch,schemaCopies:value});authorize();}
  async function member(id,coaching=false){authorize();const profile=await hooks.profile(id);authorize();const c=hooks.clients().find(x=>x.id===id);if(!c||profile.member?.client_id!==id)throw Error('Dit lid is niet toegankelijk.');if(coaching&&adapter.memberStatusRead){const status=await adapter.memberStatusRead(id);authorize();if(!status[0]?.coaching)throw Error('Nieuwe coaching is voor dit lid gepauzeerd.');}return c;}
  async function versions(id){return serial(async()=>{const c=await member(id),d=data(),groups=new Map();for(const entry of c.trainingPlan||[]){const key=entry.schemaId||entry.schemaName||'Trainingsschema';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(entry);}let changed=false;for(const [key,rows]of groups){const plan=structure(rows),hash=await sha(plan);if(!d.versions.some(v=>v.memberId===id&&v.key===key&&v.hash===hash)){d.versions.push({id:crypto.randomUUID(),memberId:id,key,name:rows[0].schemaName||'Trainingsschema',hash,number:1+d.versions.filter(v=>v.memberId===id&&v.key===key).length,recordedAt:new Date().toISOString(),plan});changed=true;}}if(changed)await write(d);return copy(d.versions.filter(v=>v.memberId===id));});}
